/**
 * Convert an 'unsigned' byte to an integer. ie, don't carry across the
 * sign.
 *
 * @param b Description of the Parameter
 * @return Description of the Return Value
 */
public static int ubyteToInt(byte b) {
    return b & 0xFF;
}
